/**
 * KS-1175 — the read-back surfaces (R9), tested through pure modules, never through the booted app
 * (index.ts calls app.listen on import — the reason anchorSchema.ts and now anchorReadback.ts are extracted).
 *
 *  (1) GET /api/anchors/verify/:hash — buildVerifyResponse: `metadata.identity` beside `metadata.identityCommitment`
 *      for BOTH the db source (metadata_payload, logical form) and the chain source (json_metadata, chunked form,
 *      after fromCardanoMetadatum). `null` for anchors that predate the field.
 *  (2) GET /api/anchors/:id — anchorIdentityView(metadataPayload.secuura): { identityCommitment, identity } — the
 *      surface Stuart names for S's local-vs-chain comparison (PS-871). null/null for a legacy row.
 *  The two booleans come back as real booleans from either source: the chain carries them as "true"/"false"
 *  (KS-1284 — Cardano metadata has no boolean type), the view restores the type.
 */

import { describe, it, expect } from 'vitest';

import { anchorIdentityView, buildVerifyResponse } from '../anchorReadback';
import { toCardanoMetadatum, fromCardanoMetadatum } from '../cardano/cardanoMetadatum';

const HASH = 'a1b2c3d4e5f60718293a4b5c6d7e8f901a2b3c4d5e6f70819203a4b5c6d7e8f9';
const COMMITMENT = `identity-commitment-l2.v1:${'b'.repeat(64)}`;
const IDENTITY = {
  actorDid: 'did:key:z6MkhaXgBZDvotDkL5257faiztiGiC2QtKLGpbnnEGta2doK',
  actorLevel: 2,
  actorSource: 'stripe',
  actorVerified: true,
  orgDid: 'did:web:acme.example',
  orgTrust: 'domain',
  orgVerified: false,
};
const LOGICAL = {
  secuura: {
    version: '2.0', type: 'document', hash: HASH, algorithm: 'sha256',
    documentId: 'doc-1777346021120-1e528170', certId: 'doc-1777346021120-1e528170',
    timestamp: '2026-09-20T12:00:00.000Z', network: 'preview', documentType: 'sign',
    occurredAt: '2026-09-16T10:36:32.000Z', identityCommitment: COMMITMENT, ...IDENTITY,
  },
};
const LEGACY = {
  secuura: {
    version: '2.0', type: 'document', hash: HASH, algorithm: 'sha256',
    documentId: 'doc-1777346021120-1e528170', certId: 'doc-1777346021120-1e528170',
    timestamp: '2026-08-01T00:00:00.000Z', network: 'preview',
  },
};
const CTX = { hash: HASH, network: 'preview' };
const ROW = {
  transaction_hash: 'f'.repeat(64), block_number: 4242, confirmed_at: '2026-09-20T12:01:00.000Z',
  created_at: '2026-09-20T12:00:00.000Z', document_id: 'doc-1777346021120-1e528170', status: 'confirmed',
};

describe('anchorIdentityView — GET /api/anchors/:id (R9)', () => {
  it('returns identityCommitment and the seven as a typed object from a logical (DB-form) payload', () => {
    expect(anchorIdentityView(LOGICAL.secuura)).toEqual({ identityCommitment: COMMITMENT, identity: IDENTITY });
  });
  it('returns null / null for a legacy row that predates both fields', () => {
    expect(anchorIdentityView(LEGACY.secuura)).toEqual({ identityCommitment: null, identity: null });
  });
  it('returns null / null for a missing or empty payload (a pending row, or a row with no secuura block)', () => {
    expect(anchorIdentityView(undefined)).toEqual({ identityCommitment: null, identity: null });
    expect(anchorIdentityView({})).toEqual({ identityCommitment: null, identity: null });
  });
  it('a partial identity block returns only the fields anchored (absent stays absent, never null-filled)', () => {
    const view = anchorIdentityView({ ...LEGACY.secuura, actorLevel: 3, orgTrust: 'kyc' });
    expect(view).toEqual({ identityCommitment: null, identity: { actorLevel: 3, orgTrust: 'kyc' } });
  });
  it('restores the two booleans from the chain form ("true"/"false") and leaves real booleans alone', () => {
    const chainForm = fromCardanoMetadatum(toCardanoMetadatum(LOGICAL)) as typeof LOGICAL;
    expect(chainForm.secuura.actorVerified).toBe('true'); // the fixture is really in chain form
    expect(anchorIdentityView(chainForm.secuura).identity).toEqual(IDENTITY);
    expect(anchorIdentityView(LOGICAL.secuura).identity).toEqual(IDENTITY);
  });
  it('never invents a key: an unknown key under secuura (e.g. a future field) is not surfaced as identity', () => {
    const view = anchorIdentityView({ ...LEGACY.secuura, actorName: 'Jane Doe' });
    expect(view.identity).toBeNull();
    expect(JSON.stringify(view)).not.toContain('Jane Doe');
  });
});

describe('buildVerifyResponse — GET /api/anchors/verify/:hash (R9)', () => {
  it('db source: metadata.identity beside metadata.identityCommitment, from the logical payload', () => {
    const body = buildVerifyResponse('db', LOGICAL, ROW, CTX);
    expect(body.metadata.identityCommitment).toBe(COMMITMENT);
    expect(body.metadata.identity).toEqual(IDENTITY);
    expect(body.metadata.documentType).toBe('sign');
    expect(body.metadata.occurredAt).toBe('2026-09-16T10:36:32.000Z');
  });

  it('chain source: the same object from a chunked chain payload once the reader has joined it', () => {
    const chunked = toCardanoMetadatum(LOGICAL) as { secuura: Record<string, unknown> };
    expect(Array.isArray(chunked.secuura.identityCommitment)).toBe(true); // the fixture really is chunked
    const onChain = {
      secuura: (fromCardanoMetadatum(chunked) as typeof LOGICAL).secuura,
      txHash: 'e'.repeat(64), blockNumber: 4243, confirmedAt: '2026-09-20T12:02:00.000Z',
    };
    const body = buildVerifyResponse('chain', onChain, undefined, CTX);
    expect(body.source).toBe('chain');
    expect(body.metadata.identityCommitment).toBe(COMMITMENT);
    expect(body.metadata.identity).toEqual(IDENTITY);
  });

  it('an anchor that predates the field reads identity: null and identityCommitment: null (both sources)', () => {
    expect(buildVerifyResponse('db', LEGACY, ROW, CTX).metadata.identity).toBeNull();
    expect(buildVerifyResponse('db', LEGACY, ROW, CTX).metadata.identityCommitment).toBeNull();
    expect(buildVerifyResponse('chain', { secuura: LEGACY.secuura, txHash: 'e'.repeat(64) }, undefined, CTX).metadata.identity).toBeNull();
  });

  it('CONTROL: the rest of the KS-522/KS-726 shape is unchanged by the extraction', () => {
    const body = buildVerifyResponse('db', LOGICAL, ROW, CTX);
    expect(body.verified).toBe(true);
    expect(body.status).toBe('confirmed');
    expect(body.acknowledged).toBe(true);
    expect(body.txHash).toBe('f'.repeat(64));
    expect(body.cardanoScanUrl).toBe(`https://preview.cardanoscan.io/transaction/${'f'.repeat(64)}`);
    expect(body.metadata.contentHash).toBe(HASH);
    // KS-522: a placeholder hash is never an on-chain claim
    const sim = buildVerifyResponse('db', LOGICAL, { ...ROW, transaction_hash: 'mock_tx_abc' }, CTX);
    expect(sim.txHash).toBeNull();
    expect(sim.simulated).toBe(true);
    expect(sim.cardanoScanUrl).toBeNull();
  });
});
